import urllib.request,urllib.error
url='https://s3.us-east-2.amazonaws.com/nclt.perl.engin.umich.edu/velodyne_data/2013-01-10_vel.tar.gz'
try:
 with urllib.request.urlopen(urllib.request.Request(url,method='HEAD'),timeout=25) as r: print({'url':url,'status':r.status,'content_length':r.headers.get('Content-Length'),'accept_ranges':r.headers.get('Accept-Ranges')})
except urllib.error.HTTPError as e:print({'url':url,'status':e.code,'body':e.read(1200).decode(errors='replace')})
